import { SAMPLE_RATE } from "../core/constants.js";
import { int16ToBytes } from "../core/pcm.js";
import { DictationStreamError } from "./dictation-stream-error.js";
import {
  DICTATION_STREAM_CLOSE_CODES,
  parseDictationStreamServerMessage,
} from "./stream-protocol.js";
// The server rejects frames over 64 KiB, so long buffers go out as 1 s (32 KB) frames.
const MAX_AUDIO_FRAME_SAMPLES = SAMPLE_RATE;
export class DictationStreamConnection {
  opened;
  socket;
  connectTimer;
  onClose;
  resolveOpened;
  rejectOpened;
  closed = false;
  constructor(options) {
    this.onClose = options.onClose;
    this.opened = new Promise((resolve, reject) => {
      this.resolveOpened = resolve;
      this.rejectOpened = reject;
    });
    this.opened.catch(() => undefined);
    this.socket = new options.WebSocket(options.url);
    this.socket.addEventListener("open", () => {
      clearTimeout(this.connectTimer);
      this.resolveOpened();
    });
    this.socket.addEventListener("message", (event) => {
      // Some socket implementations still deliver frames after close(); they belong to a dropped dictation.
      if (this.closed) return;
      const message = parseDictationStreamServerMessage(event.data);
      if (message) options.onMessage(message);
    });
    this.socket.addEventListener("close", (event) => {
      this.drop(
        new DictationStreamError(
          "connection_closed",
          closeMessage(event.reason),
          event.code
        )
      );
    });
    this.socket.addEventListener("error", () => {
      this.drop(
        new DictationStreamError("connection_closed", "Dictation stream failed")
      );
      this.socket.close();
    });
    this.connectTimer = setTimeout(() => {
      this.drop(
        new DictationStreamError(
          "connect_timeout",
          "Dictation stream connect timed out"
        )
      );
      this.socket.close();
    }, options.connectTimeoutMs);
  }
  sendJson(message) {
    this.socket.send(JSON.stringify(message));
  }
  sendAudio(pcm) {
    for (
      let offset = 0;
      offset < pcm.length;
      offset += MAX_AUDIO_FRAME_SAMPLES
    ) {
      const frame = pcm.subarray(offset, offset + MAX_AUDIO_FRAME_SAMPLES);
      this.socket.send(int16ToBytes(frame).buffer);
    }
  }
  close() {
    this.markClosed(
      new DictationStreamError("connection_closed", "Dictation stream closed")
    );
    this.socket.close(DICTATION_STREAM_CLOSE_CODES.normal);
  }
  drop(error) {
    if (this.closed) return;
    this.markClosed(error);
    this.onClose(error);
  }
  markClosed(error) {
    this.closed = true;
    clearTimeout(this.connectTimer);
    this.rejectOpened(error);
  }
}
function closeMessage(reason) {
  if (reason) return `Dictation stream closed: ${reason}`;
  return "Dictation stream closed";
}
